/** Original pixel size of each art piece, as the master lays it out. */
export const LETTERHEAD_ART_SIZE = {
  skSeal: { width: 88.8, height: 76.66,
    emu: { width: 845820, height: 730250 } },
  flagBanner: { width: 880.8, height: 212.6,
    emu: { width: 8389620, height: 2025015 } },
  barangaySeal: { width: 92.8, height: 92.8,
    emu: { width: 883920, height: 883920 } },
  citySeal: { width: 94, height: 94,
    emu: { width: 895350, height: 895350 } },
};

function decode(base64) {
  if (typeof atob === "function") {
    const binary = atob(base64);
    const out = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i += 1) out[i] = binary.charCodeAt(i);
    return out;
  }
  return Buffer.from(base64, "base64");
}

let cached = null;

/**
 * Decodes the four letterhead images. Cached: a document set is generated
 * repeatedly against one process or one browser session.
 *
 * @returns {Promise<{ skSeal: Uint8Array, flagBanner: Uint8Array,
 *   barangaySeal: Uint8Array, citySeal: Uint8Array }>}
 */
export async function loadLetterheadArt() {
  if (cached) return cached;
  cached = {
    skSeal: decode(SK_SEAL),
    flagBanner: decode(FLAG_BANNER),
    barangaySeal: decode(BARANGAY_SEAL),
    citySeal: decode(CITY_SEAL),
  };
  return cached;
}
